// ContextWaiter is the sibling of Process (ADR 0039) that bounds a wait: the
// handle Start returns implements it, a Process from elsewhere may not.
type ContextWaiter interface {
	// WaitContext waits like Wait until the process exits or ctx is done. When
	// ctx ends first it returns ctx's error and the child keeps running; a later
	// Wait or WaitContext still reports the real exit.
	WaitContext(ctx context.Context) (ExitValue, error)
}

// Group is a handle to a cgroup v2 control group used to confine a process tree:
// set controller limits, attach processes, and remove the group. Implementations
// live in internal/service/proc/*; it is Linux-only and non-Linux builds return
// a no-op satisfying this interface with UNSUPPORTED_PLATFORM.
type Group interface {
	// SetMemoryMax writes memory.max (systemd MemoryMax=); a negative value
	// means "max" (no limit).
	SetMemoryMax(bytes int64) error
	// SetCPUMax writes cpu.max as "quota period" (systemd CPUQuota=); a negative
	// quota means "max".
	SetCPUMax(quota, period int64) error
	// SetPidsMax writes pids.max (systemd TasksMax=); a negative value means
	// "max".
	SetPidsMax(n int64) error
	// SetIOMax writes one io.max line verbatim (systemd IO*Max=), e.g.
	// "8:0 rbps=1048576".
	SetIOMax(spec string) error
	// Add moves the process pid into this group by writing cgroup.procs.
	Add(pid int) error
	// Kill atomically SIGKILLs every process in the group by writing "1" to
	// cgroup.kill (systemd KillMode=control-group; kernel >= 5.14). Unlike a
	// process-group kill, nothing escapes — a member that called setsid is still
	// in the control group. Returns UnsupportedPlatform when cgroup.kill is absent
	// (older kernels), so callers can fall back to SignalGroup.
	//
	// Kill a group nothing will be spawned into again: on Linux (measured on
	// 6.12), after one cgroup.kill — an empty group's too — every child later
	// cloned into the group (Spec.CgroupPath, CLONE_INTO_CGROUP) is SIGKILLed at
	// its fork, while a process moved in by Add is not. To empty a group that
	// will be reused, signal its members instead (GroupSignaler's Signal).
	Kill() error
	// Freeze quiesces the whole group by writing "1" to cgroup.freeze (kernel
	// >= 5.2), stopping every member so a consistent signal sweep or snapshot can
	// run. Returns UnsupportedPlatform when cgroup.freeze is absent. Idempotent.
	Freeze() error
	// Thaw resumes a frozen group by writing "0" to cgroup.freeze. Returns
	// UnsupportedPlatform when cgroup.freeze is absent. Idempotent.
	Thaw() error
	// Delete removes the (empty) control group; callers move processes out first.
	Delete() error
}

// GroupReader is the read half a control group may offer beside Group (ADR
// 0039, asserted on the Group cgroup.Create returns): what the confined tree
// has used. A backend reads what its kernel counts and says what it cannot
// with GroupStatValue.Partial; a platform with no control group has no
// GroupReader.
type GroupReader interface {
	// Stat reads the group's counters: CPU time and throttling, memory now, at
	// its peak and the events of its limits, the pid count, the I/O per device.
	// It returns CgroupReadFailed when the group's own files cannot be read —
	// the group was deleted.
	Stat() (GroupStatValue, error)
	// Members lists the pids of the group's processes and of the groups
	// beneath it — the cgroup.procs of the subtree, the tracked set, the
	// job's process list — in no promised order: a process a delegated
	// service moved into a group of its own is still the group's.
	Members() ([]int, error)
}

// GroupSignaler is the sibling of Group (ADR 0039, asserted on the Group
// cgroup.Create returns on Linux) that reaches every process of the group and
// of the groups beneath it — systemd's KillMode=control-group and mixed. With
// Group's Kill it is what proc/service's CgroupKill asks of a unit's group.
type GroupSignaler interface {
	// Signal sends sig to every process of the group and of the groups beneath
	// it but the caller's own, reading cgroup.procs again until a pass finds no
	// process it has not signalled, at most 64 passes. A process gone before the
	// signal reached it is not an error; any other refusal is SignalFailed.
	Signal(sig Signal) error
	// Contains reports whether pid is a process of the group or of a group
	// beneath it. CgroupReadFailed when the group's cgroup.procs cannot be read.
	Contains(pid int) (bool, error)
}

// GroupTree is the sibling of Group (ADR 0039, asserted on the Group
// cgroup.Create returns on Linux) for the group as a node of the hierarchy:
// its directory, the controllers the groups beneath it get, its delegation
// to another user, and its removal with what was made beneath it.
type GroupTree interface {
	// Path is the group's directory: the CgroupPath a Spec spawns a child straight into.
	Path() string
	// EnableControllers writes ctrls to the group's cgroup.subtree_control, so
	// the groups beneath it get their interface files. A controller the group's
	// cgroup.controllers does not list is CgroupControllerAbsent, and a
	// malformed name InvalidSpec, before anything is written; while the group
	// itself holds a process the kernel refuses with EBUSY, CgroupWriteFailed
	// (cgroup v2's no-internal-process rule).
	EnableControllers(ctrls ...Controller) error
	// Delegate hands the group to the user uid and the group gid (systemd
	// Delegate=yes): it changes the owner of the directory and of the files the
	// kernel lists in /sys/kernel/cgroup/delegate — cgroup.procs,
	// cgroup.threads and cgroup.subtree_control where that list is absent — so
	// that user may create groups beneath it, move its processes and enable
	// controllers. -1 keeps an owner unchanged. A file the group lacks is
	// skipped; a refused change is CgroupWriteFailed.
	Delegate(uid, gid int) error
	// DeleteTree removes the group and every group beneath it, deepest first:
	// what a delegated unit made under its group goes with it, as systemd
	// cleans a Delegate=yes unit up. A group still holding a process stops it
	// with CgroupDeleteFailed naming that group — Kill, and wait for Watch to
	// say the group is empty, first. A link is never followed.
	DeleteTree() error
}

// GroupTuner is the sibling of Group (ADR 0039, asserted on the Group
// cgroup.Create returns on Linux) that writes the cgroup v2 interface files
// Group does not: the memory protections and throttle, the swap and zswap
// limits, the OOM grouping, the CPU weight and burst, the cpusets, the I/O
// weight and latency. Each setter writes one file of the group, which exists
// only when the parent enables its controller (WithControllers,
// GroupTree.EnableControllers): a write to an absent file is
// CgroupWriteFailed. A value outside the kernel's range is InvalidSpec, and
// nothing is written.
