// whole. Group's SetMemoryMax is unchanged.
type JobLimiter interface {
	// SetJobMemoryLimit caps the memory committed by every process of the job
	// together (JOB_OBJECT_LIMIT_JOB_MEMORY); a negative value removes the cap.
	// CgroupWriteFailed when the job refuses it.
	SetJobMemoryLimit(bytes int64) error
}

// Listener is the supervisor side of the sd_notify protocol: it owns the
// AF_UNIX datagram socket a supervised child writes readiness to, and yields one
// parsed, credential-verified NotificationValue per received datagram.
// Implementations live in internal/service/proc/*.
type Listener interface {
	// Recv blocks until the next datagram arrives and returns it parsed, with the
	// sender PID verified by the kernel. It returns a typed error on a malformed
	// datagram or once the listener is closed.
	Recv() (NotificationValue, error)
	// Close releases the socket and unblocks any in-flight Recv.
	Close() error
}

// Process is a handle to a spawned process. It exposes only lifetime control —
// observe completion, deliver a signal to the leader or its whole group, and
// stop it gracefully. Implementations live in internal/service/proc/*; the
// pkg/v1/proc/process facade returns this interface.
type Process interface {
	// PID reports the process identifier of the leader.
	PID() int
	// Wait blocks until the process exits and returns its ExitValue — the real
	// one even when a running Reaper collected the child first. It is safe
	// to call once; concurrent or repeated calls observe the same outcome. Under
	// StdioCapture it returns only after every captured byte has reached the
	// caller's writers; if a writer itself failed, the ExitValue still reports the
	// real exit status and the error is StdioCaptureFailed. A process the child
	// left behind can hold its output pipe past the exit: Spec.DrainGrace bounds
	// that wait, after which the pipes are closed and the error, beside the real
	// ExitValue, is StdioDrainTimeout.
	Wait() (ExitValue, error)
	// Signal delivers sig to the leader process only.
	Signal(sig Signal) error
	// SignalGroup delivers sig to the leader's entire process group (kill(-pgid,
	// sig)), reaching forked grandchildren — the KillMode=control-group analogue.
	// On Windows a Setpgid child's console process group receives the matching
	// console control event instead — CTRL_C for SIGINT, CTRL_BREAK for SIGTERM,
	// SIGHUP and SIGQUIT — and SIGKILL, or any signal to a child without its own
	// group, reaches the leader alone.
	SignalGroup(sig Signal) error
	// Stop terminates the process group gracefully: it sends sig, waits up to
	// grace for exit, then escalates to SIGKILL. It returns when the process has
	// exited or ctx is cancelled. On Windows sig reaches a Setpgid child as its
	// console control event, as SignalGroup sends it, and the escalation is
	// TerminateProcess.
	Stop(ctx context.Context, grace time.Duration, sig Signal) error
}

// ProcessHandle is the sibling of Process (ADR 0039) that reaches the process
// through a kernel handle rather than its pid, which another process may hold
// once this one is reaped: a pidfd on Linux 5.4 and later, the process HANDLE on
// Windows. The handles Start and Open return implement it.
type ProcessHandle interface {
	// Handle returns a new descriptor for the process, which the caller owns and
	// closes: a pidfd on Linux — readable once the process exits, so it can be
	// polled, or passed to another process — and a duplicated process HANDLE on
	// Windows. It reports false where none is available: a kernel without pidfd,
	// another platform, or a process already reaped.
	Handle() (*os.File, bool)
	// SignalHandle delivers sig through the process's kernel handle
	// (pidfd_send_signal on Linux), never by pid: once the process is reaped it
	// fails with SignalFailed wrapping ESRCH instead of reaching a process that
	// reused the pid. It returns HandleUnavailable where the kernel gave no handle,
	// and UnsupportedPlatform off Linux and Windows.
	SignalHandle(sig Signal) error
}

// Reaper collects terminated child processes so they do not linger as zombies —
// the core duty of any PID1 or subreaper. Implementations live in
// internal/service/proc/*; non-supporting platforms return a no-op reaper.
//
// A sweep collects every exited child, including one a Process handle is
// waiting for; an implementation must hand such a child's exit status to that
// Process rather than discard it, so its Wait still reports the real exit.
type Reaper interface {
	// Start begins a background SIGCHLD-driven loop that reaps children as they
	// exit. It is idempotent: a second Start while running is a no-op.
	Start()
	// Stop ends the background loop after a final draining sweep, so shutdown
	// leaves no un-reaped zombies. It is safe to call without a prior Start.
	Stop()
	// ReapOnce performs a single non-blocking sweep and reports how many
	// children were reaped. It is safe to call concurrently with the loop.
	ReapOnce() (int, error)
}

